import { PilotProposal } from '@/types';

export function formatProposalMarkdown(p: PilotProposal): string {
  return `# PROOF-OF-CONCEPT PILOT PROPOSAL
**${p.challengeTitle}**

*Generated by ASEAN POC-Architect — Turn ASEAN business connections into actionable proof-of-concepts.*

---

## Metadata & Executive Overview
- **Enterprise Partner:** ${p.enterpriseName}
- **Startup Partner:** ${p.startupName} (${p.startupCountry})
- **Proposal ID:** \`${p.id}\`
- **Version:** v${p.version}.0 (${p.status})
- **Date:** ${new Date(p.updatedAt).toLocaleDateString('en-SG', { year: 'numeric', month: 'long', day: 'numeric' })}

---

## 1. Executive Summary
${p.executiveSummary}

---

## 2. Problem Statement & Proposed Solution
### Problem Statement
${p.problemStatement}

### Proposed Solution
${p.proposedSolution}

---

## 3. Scope & Architecture
### In-Scope Deliverables
${p.inScope.map((item) => `- [x] ${item}`).join('\n')}

### Out-of-Scope Exclusions
${p.outOfScope.map((item) => `- [ ] ${item}`).join('\n')}

### Integration Architecture
${p.integrationArchitecture}

---

## 4. Pilot Milestones & Delivery Schedule
${p.milestones
  .map(
    (m, idx) => `### Milestone ${idx + 1}: ${m.title} (${m.phase})
- **Duration:** ${m.durationWeeks} weeks
- **Key Deliverables:**
${m.deliverables.map((d) => `  - ${d}`).join('\n')}
- **Acceptance Criteria:** ${m.acceptanceCriteria}
`
  )
  .join('\n')}

---

## 5. Governance & RACI Responsibility Matrix
| Activity / Deliverable | Enterprise Role | Startup Role | Notes |
| :--- | :---: | :---: | :--- |
${p.raciMatrix
  .map((r) => `| ${r.activity} | **${r.enterpriseRole}** | **${r.startupRole}** | ${r.notes} |`)
  .join('\n')}

*RACI Legend: R = Responsible, A = Accountable, C = Consulted, I = Informed*

---

## 6. Target KPIs & Measurement Framework
| Metric | Baseline | Target | Measurement Method |
| :--- | :--- | :--- | :--- |
${p.kpis
  .map((k) => `| **${k.metric}** | ${k.baseline} | **${k.target}** | ${k.measurementMethod} |`)
  .join('\n')}

---

## 7. Risks, Compliance & Sovereign Data Residency
### Technical Risks & Mitigations
${p.technicalRisks.map((r) => `- **Risk:** ${r}`).join('\n')}

### Data Residency Plan
${p.dataResidencyPlan}

### Open Questions for Pilot Kickoff
${p.openQuestions.map((q) => `- ${q}`).join('\n')}

---

## 8. Provenance & Verification Audit Trail
### [VERIFIED INFORMATION] (Startup Ground Truth)
${p.provenance.verifiedStartupFacts.map((f) => `- ${f}`).join('\n')}

### [ENTERPRISE SUPPLIED] (Client Constraints)
${p.provenance.enterpriseSuppliedInputs.map((i) => `- ${i}`).join('\n')}

### [AI GENERATED SUGGESTIONS] (Synthesis & Architecture)
${p.provenance.aiGeneratedSections.map((s) => `- ${s}`).join('\n')}

---

## 9. Legal Disclaimer
> **IMPORTANT ADVISORY:** ${p.legalDisclaimer}
`;
}

export function downloadFile(content: string, filename: string, mimeType: string) {
  const blob = new Blob([content], { type: mimeType });
  const url = URL.createObjectURL(blob);
  const a = document.createElement('a');
  a.href = url;
  a.download = filename;
  document.body.appendChild(a);
  a.click();
  document.body.removeChild(a);
  URL.revokeObjectURL(url);
}
